  ('pilsner', '{"id":"pilsner","sort":30,"name":{"en":"BRIGHT STAR PILSNER","ja":"BRIGHT STAR PILSNER","ko":"브라이트 스타 필스너","zh-Hans":"BRIGHT STAR 皮尔森啤酒","zh-Hant":"BRIGHT STAR 皮爾森啤酒"},"unit":null,"group":"beer","serve":null,"origin":{"en":"Craft beer from Yame, Fukuoka","ja":"福岡県八女産クラフトビール","ko":"후쿠오카현 야메산 수제 맥주","zh-Hans":"福冈县八女精酿啤酒","zh-Hant":"福岡縣八女精釀啤酒"},"category":"alcohol","priceNote":null,"description":{"en":"Pilsner brewed with Yame tea. Low‑temperature fermentation and long ageing give a crisp, clean taste.","ja":"八女茶を使ったピルスナー。低温での発酵と長期熟成による、さっぱりとした飲み口。","ko":"야메차를 사용한 필스너입니다. 저온 발효와 장기 숙성으로 깔끔한 맛을 냅니다.","zh-Hans":"使用八女茶酿制的皮尔森啤酒。低温发酵与长期熟成带来清爽口感。","zh-Hant":"使用八女茶釀製的皮爾森啤酒。低溫發酵與長期熟成帶來清爽口感。"}}'::jsonb, 1200, true, false, 30),
  ('ipa', '{"id":"ipa","sort":31,"name":{"en":"FUKAMUSHI IPA","ja":"FUKAMUSHI IPA","ko":"후카무시 IPA","zh-Hans":"FUKAMUSHI 深蒸茶 IPA","zh-Hant":"FUKAMUSHI 深蒸茶 IPA"},"unit":null,"group":"beer","serve":null,"origin":{"en":"Craft beer from Yame, Fukuoka","ja":"福岡県八女産クラフトビール","ko":"후쿠오카현 야메산 수제 맥주","zh-Hans":"福冈县八女精酿啤酒","zh-Hant":"福岡縣八女精釀啤酒"},"category":"alcohol","priceNote":null,"description":{"en":"IPA brewed with deep‑steamed Yame tea. Strong citrusy hop aroma and bitterness.","ja":"深蒸し八女茶を使ったIPA。強い柑橘系ホップの香りと苦味が特長。","ko":"깊게 찐 야메차를 사용한 IPA입니다. 강한 감귤류 홉 향과 쓴맛이 특징입니다.","zh-Hans":"使用深蒸八女茶酿制的IPA，带有浓郁的柑橘酒花香与苦味。","zh-Hant":"使用深蒸八女茶釀製的IPA，帶有濃郁的柑橘酒花香與苦味。"}}'::jsonb, 1200, true, false, 31),
  ('gyokuro-ume-sour', '{"id":"gyokuro-ume-sour","sort":32,"name":{"en":"Gyokuro Ume Sour","ja":"玉露梅サワー","ko":"교쿠로 매실 사와","zh-Hans":"玉露梅沙瓦","zh-Hant":"玉露梅沙瓦"},"unit":null,"group":"sour","serve":null,"origin":null,"category":"alcohol","priceNote":{"en":"Refills ¥600","ja":"2杯目以降 600円","ko":"두 번째 잔부터 600엔","zh-Hans":"第二杯起600日元","zh-Hant":"第二杯起600日圓"},"description":{"en":"Our original plum sour: house‑made tea shochu with soda and a house‑made gyokuro ume plum. Crush the plum or not, as you like. Refill the same glass with tea shochu and soda.","ja":"自家製のお茶焼酎を炭酸水で割り、自家製の玉露梅を入れたオリジナル梅サワー。梅はつぶしても、そのままでも。グラスそのままで、お茶焼酎と炭酸水のおかわりができます。","ko":"직접 만든 차 소주에 탄산수와 수제 교쿠로 매실을 넣었습니다. 매실은 으깨거나 그대로 즐기세요. 같은 잔에 차 소주와 탄산수를 리필할 수 있습니다.","zh-Hans":"自制茶烧酒加苏打水与自制玉露梅。梅子可捣碎或直接享用，可用原杯续加茶烧酒与苏打水。","zh-Hant":"自製茶燒酎加蘇打水與自製玉露梅。梅子可搗碎或直接享用，可用原杯續加茶燒酎與蘇打水。"}}'::jsonb, 800, true, false, 32)
